	case "json":
		return renderWebhookGetJSON, nil
	default:
		return nil, fmt.Errorf("invalid --output value %q: expected \"default\" or \"json\"", output)
	}
}

// webhookGetJSON is the full JSON shape for `pulumi stack webhook get --output=json`.
