	scheduleKindRaw   = "raw"
	scheduleKindDrift = "drift"
	scheduleKindTTL   = "ttl"
)

// scheduleSummary is a flattened, human-readable summary of a scheduled action.
// It is used as the JSON output shape for the list and get commands. The ID
// field is exported to allow JSON deserialization by tests.
type scheduleSummary struct {
	ID       string `json:"id"`
	Type     string `json:"type"`
	Settings string `json:"settings"`
	Schedule string `json:"schedule"`
	NextRun  string `json:"nextRun,omitempty"`
	LastRun  string `json:"lastRun,omitempty"`
	Created  string `json:"created,omitempty"`
}

// scheduleGetRenderFunc renders a single scheduled action.
