// scheduleListRenderFunc renders a list of scheduled actions.
type scheduleListRenderFunc func(w io.Writer, schedules []apitype.ScheduledAction) error

// scheduleDefinitionOf parses the schedule's Definition into a deployment definition.
func scheduleDefinitionOf(s apitype.ScheduledAction) apitype.ScheduledDeploymentDefinition {
	var def apitype.ScheduledDeploymentDefinition
	if len(s.Definition) > 0 {
		_ = json.Unmarshal(s.Definition, &def)
	}
	return def
}

// scheduleKindOf infers the schedule kind (raw, drift, or ttl) from a scheduled
// action's definition and timing fields.
func scheduleKindOf(s apitype.ScheduledAction) string {
	def := scheduleDefinitionOf(s)
	var op apitype.PulumiOperation
	if def.Request != nil {
		op = def.Request.Op
	}
	switch {
	case op == apitype.Destroy && s.ScheduleOnce != "":
		return scheduleKindTTL
	case op == apitype.DetectDrift:
		return scheduleKindDrift
	default:
		return scheduleKindRaw
	}
}

// toScheduleSummary converts a scheduled action into a flattened summary.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	def := scheduleDefinitionOf(s)
	var op apitype.PulumiOperation
	var deleteAfterDestroy bool
	if def.Request != nil {
		op = def.Request.Op
		if def.Request.Operation != nil && def.Request.Operation.Options != nil {
			deleteAfterDestroy = def.Request.Operation.Options.DeleteAfterDestroy
		}
	}

	schedule := s.ScheduleCron
	if schedule == "" && s.ScheduleOnce != "" {
		schedule = "Once"
	}

	var typ, settings string
	switch {
	case op == apitype.Destroy && s.ScheduleOnce != "":
		typ = scheduleKindTTL
		schedule = "Once"
		if deleteAfterDestroy {
			settings = "destroy + delete stack"
		} else {
			settings = "destroy"
		}
	case op == apitype.DetectDrift:
		typ = scheduleKindDrift
		settings = "detect"
	default:
		typ = scheduleKindRaw
		settings = "pulumi " + string(op)
	}

	summary := scheduleSummary{
		ID:       s.ID,
		Type:     typ,
		Settings: settings,
		Schedule: schedule,
		NextRun:  s.NextExecution,
		Created:  s.Created,
	}
	if s.LastExecuted != nil {
		summary.LastRun = *s.LastExecuted
	}
	return summary
}

