func TestScratchSummaryTypes(t *testing.T) {
	// TTL destroy once
	ttl := apitype.ScheduledAction{ID: "1", ScheduleOnce: "2026-01-01T00:00:00Z",
		Definition: mkDef(t, apitype.Destroy, &apitype.OperationContextOptions{DeleteAfterDestroy: false})}
	s := toScheduleSummary(ttl)
	assert.Equal(t, "ttl", s.Type)
	assert.Equal(t, "Once", s.Schedule)
	assert.Equal(t, "destroy", s.Settings)

	ttl2 := apitype.ScheduledAction{ID: "1", ScheduleOnce: "x",
		Definition: mkDef(t, apitype.Destroy, &apitype.OperationContextOptions{DeleteAfterDestroy: true})}
	assert.Equal(t, "destroy + delete stack", toScheduleSummary(ttl2).Settings)

	drift := apitype.ScheduledAction{ID: "2", ScheduleCron: "0 * * * *", Definition: mkDef(t, apitype.DetectDrift, nil)}
	sd := toScheduleSummary(drift)
	assert.Equal(t, "drift", sd.Type)
	assert.Equal(t, "detect", sd.Settings)

	raw := apitype.ScheduledAction{ID: "3", ScheduleCron: "0 * * * *", Definition: mkDef(t, apitype.Refresh, nil)}
	sr := toScheduleSummary(raw)
	assert.Equal(t, "raw", sr.Type)
	assert.Equal(t, "pulumi refresh", sr.Settings)
}

